<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';
require_once __DIR__.'/_helper.php';
bk_require_access($pdo);
header('Content-Type: application/json; charset=utf-8');
function bl_json(array $d,int $s=200):never{http_response_code($s);echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function bl_student(PDO $pdo,string $qr):?array{$st=$pdo->prepare("SELECT s.id,s.nis,s.nisn,s.nama,s.kode_qr,s.status,COALESCE(mk.nama,'-') kelas,sk.tahun_pelajaran_id,sk.kelas_id FROM siswa s LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 JOIN tahun_pelajaran tp2 ON tp2.id=sk2.tahun_pelajaran_id WHERE sk2.siswa_id=s.id AND sk2.status='aktif' AND tp2.aktif=1 ORDER BY sk2.id DESC LIMIT 1) LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id WHERE s.kode_qr=? LIMIT 1");$st->execute([$qr]);return $st->fetch()?:null;}
function bl_enqueue(PDO $pdo,int $sid,string $metode):array{ $s=bk_get_student($pdo,$sid); if(!$s) throw new RuntimeException('Siswa tidak ditemukan.'); $ctx=$pdo->prepare("SELECT sk.tahun_pelajaran_id,sk.kelas_id FROM siswa_kelas sk JOIN tahun_pelajaran tp ON tp.id=sk.tahun_pelajaran_id WHERE sk.siswa_id=? AND sk.status='aktif' AND tp.aktif=1 ORDER BY sk.id DESC LIMIT 1");$ctx->execute([$sid]);$c=$ctx->fetch();if(!$c)throw new RuntimeException('Kelas/tahun pelajaran aktif siswa tidak ditemukan.');
 $dup=$pdo->prepare("SELECT id,nomor_antrian,status,waktu_masuk FROM bk_layanan WHERE siswa_id=? AND tanggal=? AND status IN ('menunggu','dilayani') ORDER BY id DESC LIMIT 1");$dup->execute([$sid,date('Y-m-d')]);if($d=$dup->fetch())return ['duplicate'=>true,'id'=>(int)$d['id'],'nomor'=>(int)$d['nomor_antrian'],'status'=>$d['status'],'waktu'=>$d['waktu_masuk'],'student'=>$s];
 $pdo->beginTransaction();try{$stMax=$pdo->prepare("SELECT COALESCE(MAX(nomor_antrian),0)+1 FROM bk_layanan WHERE tanggal=?");$stMax->execute([date('Y-m-d')]);$n=(int)$stMax->fetchColumn();$st=$pdo->prepare("INSERT INTO bk_layanan(siswa_id,tahun_pelajaran_id,kelas_id,tanggal,nomor_antrian,waktu_masuk,metode_masuk,petugas_id,created_by) VALUES(?,?,?,?,?,NOW(),?,?,?)");$gid=bk_current_guru_id($pdo);$st->execute([$sid,(int)$c['tahun_pelajaran_id'],(int)$c['kelas_id'],date('Y-m-d'),$n,$metode,$gid?:null,(int)($_SESSION['user_id']??0)?:null]);$id=(int)$pdo->lastInsertId();$pdo->commit();bk_audit($pdo,'layanan_queue_create',$id,'Siswa masuk antrian Layanan BK: '.$s['nis']);return ['duplicate'=>false,'id'=>$id,'nomor'=>$n,'status'=>'menunggu','waktu'=>date('Y-m-d H:i:s'),'student'=>$s];}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
$action=(string)($_POST['action']??$_GET['action']??'');
if($action==='queue'){
 $st=$pdo->prepare("SELECT bl.id,bl.nomor_antrian,bl.status,bl.waktu_masuk,bl.waktu_mulai,bl.waktu_selesai,bl.jenis_layanan,s.nis,s.nisn,s.nama,mk.nama AS kelas FROM bk_layanan bl JOIN siswa s ON s.id=bl.siswa_id LEFT JOIN master_kelas mk ON mk.id=bl.kelas_id WHERE bl.tanggal=? ORDER BY bl.nomor_antrian ASC");
 $st->execute([date('Y-m-d')]);
 $data=$st->fetchAll();
 if(user_role()==='kepala_sekolah'){
  $data=array_map(static function(array $r):array{unset($r['jenis_layanan'],$r['waktu_mulai'],$r['waktu_selesai']);return $r;},$data);
 }
 bl_json(['ok'=>true,'data'=>$data]);
}
if($action==='lookup'){$q=trim((string)($_GET['q']??''));if(mb_strlen($q)<2)bl_json(['ok'=>true,'data'=>[]]);$like='%'.$q.'%';$st=$pdo->prepare("SELECT s.id,s.nis,s.nisn,s.nama,s.kode_qr,COALESCE(mk.nama,'-') kelas FROM siswa s LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 JOIN tahun_pelajaran tp2 ON tp2.id=sk2.tahun_pelajaran_id WHERE sk2.siswa_id=s.id AND sk2.status='aktif' AND tp2.aktif=1 ORDER BY sk2.id DESC LIMIT 1) LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id WHERE s.status='aktif' AND (s.nama LIKE ? OR s.nis LIKE ? OR s.nisn LIKE ? OR s.kode_qr LIKE ?) ORDER BY s.nama LIMIT 20");$st->execute([$like,$like,$like,$like]);bl_json(['ok'=>true,'data'=>$st->fetchAll()]);}
if(in_array($action,['enqueue','start','finish','cancel'],true)){
 if(user_role()==='kepala_sekolah')bl_json(['ok'=>false,'message'=>'Mode monitoring tidak dapat mengubah antrian.'],403);if($_SERVER['REQUEST_METHOD']!=='POST')bl_json(['ok'=>false,'message'=>'Metode tidak valid.'],405);require_valid_csrf();
 try{
  if($action==='enqueue'){try { sekolah_require_operasional_aktif($pdo); } catch (RuntimeException $e) { bl_json(['ok'=>false,'message'=>$e->getMessage()],422); }$qr=trim((string)($_POST['kode_qr']??''));$met=strtoupper((string)($_POST['metode']??'QR'));if(!in_array($met,['QR','USB','MANUAL'],true))$met='QR';$s=bl_student($pdo,$qr);if(!$s||$s['status']!=='aktif')bl_json(['ok'=>false,'message'=>'QR siswa tidak ditemukan atau siswa tidak aktif.'],404);$r=bl_enqueue($pdo,(int)$s['id'],$met);bl_json(['ok'=>true]+$r);}
  $id=(int)($_POST['id']??0);if($id<=0)bl_json(['ok'=>false,'message'=>'ID layanan tidak valid.'],422);$st=$pdo->prepare('SELECT * FROM bk_layanan WHERE id=? LIMIT 1');$st->execute([$id]);$row=$st->fetch();if(!$row)bl_json(['ok'=>false,'message'=>'Antrian tidak ditemukan.'],404);
  if($action==='start'){$jenis=(string)($_POST['jenis_layanan']??'');if(!in_array($jenis,['konseling','konsultasi','rujukan','administratif','lainnya'],true))bl_json(['ok'=>false,'message'=>'Jenis layanan wajib dipilih.'],422);$st=$pdo->prepare("UPDATE bk_layanan SET status='dilayani',jenis_layanan=?,waktu_mulai=NOW(),petugas_id=? WHERE id=? AND status='menunggu'");$st->execute([$jenis,bk_current_guru_id($pdo)?:null,$id]);if($st->rowCount()!==1)bl_json(['ok'=>false,'message'=>'Antrian sudah berubah atau tidak lagi menunggu.'],409);bk_audit($pdo,'layanan_start',$id,'Memulai layanan BK');bl_json(['ok'=>true]);}
  if($action==='finish'){$topik=trim((string)($_POST['topik']??''));$hasil=trim((string)($_POST['hasil']??''));$kes=trim((string)($_POST['kesepakatan']??''));$tl=trim((string)($_POST['tindak_lanjut']??''));$per=trim((string)($_POST['permasalahan']??''));$ortu=isset($_POST['melibatkan_ortu'])?1:0;if($row['status']!=='dilayani')bl_json(['ok'=>false,'message'=>'Layanan belum berstatus Dilayani.'],409);$st=$pdo->prepare("UPDATE bk_layanan SET status='selesai',topik=?,permasalahan=?,hasil=?,kesepakatan=?,tindak_lanjut=?,melibatkan_ortu=?,waktu_selesai=NOW() WHERE id=? AND status='dilayani'");$st->execute([$topik?:null,$per?:null,$hasil?:null,$kes?:null,$tl?:null,$ortu,$id]);if($st->rowCount()!==1)bl_json(['ok'=>false,'message'=>'Layanan belum berubah menjadi selesai. Data mungkin sudah berubah atau tidak lagi berstatus Dilayani.'],409);bk_audit($pdo,'layanan_finish',$id,'Menyelesaikan layanan BK');bl_json(['ok'=>true,'status'=>'selesai','id'=>$id]);}
  if($action==='cancel'){$st=$pdo->prepare("UPDATE bk_layanan SET status='batal',waktu_selesai=NOW() WHERE id=? AND status IN ('menunggu','dilayani')");$st->execute([$id]);bk_audit($pdo,'layanan_cancel',$id,'Membatalkan antrian/layanan BK');bl_json(['ok'=>true]);}
 }catch(Throwable $e){bl_json(['ok'=>false,'message'=>'Gagal memproses Layanan BK: '.$e->getMessage()],500);}
}
bl_json(['ok'=>false,'message'=>'Aksi tidak valid.'],400);
